export type IconName = keyof typeof icons;
export const iconNames = Object.keys(icons) as IconName[];

const elements = {
  circle: Circle,
  line: Line,
  path: Path,
  polyline: Polyline,
  rect: Rect,
} as unknown as Record<string, React.ComponentType<Record<string, string | number>>>;

export type IconProps = {
  name: IconName;
  /** Width and height in points. */
  size?: number;
  /** Stroke color. Defaults to the theme foreground. */
  color?: string;
  strokeWidth?: number;
  /** Fill the shape (for heart, star, bookmark…). */
  fill?: string;
};

export function Icon({ name, size = 20, color, strokeWidth = 2, fill = "none" }: IconProps) {
  const { colors } = useTheme();
  const stroke = color ?? colors.foreground;
  return (
    <Svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={fill}
      stroke={stroke}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {(icons[name] as Node[]).map(([tag, attrs], i) => {
        const El = elements[tag];
        return <El key={i} {...attrs} />;
      })}
    </Svg>
  );
}
